@startuml

class SensorController {
  + username : string
  + password : string
}

class Apartment {
  + address : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : int
  + description : string
  + unit : Unit
  + room : Room
}

class TemperatureSensor {
  + minValue : float
  + maxValue : float
}

class PowerSensor {
  + counterReading : long
}

enum Unit {
  CELSIUS
  WATT
}

class SensorValue {
  + timestamp : datetime
  + value : double
}

class Threshold {
  + thresholdValue : float
  + emailAddress : string
}

class EMonitor {}

class Admin {
  + adminId : int
}

SensorController "1" --> "* apartment" Apartment
Apartment "1" *-- "* rooms" Room
Room "1" *-- "* sensors" Sensor
Sensor "0..*" -- "*" SensorValue
Sensor "0..1" -- "1 threshold" Threshold
EMonitor "1" ..|> SensorController
Admin "1" ..|> User

@enduml

